Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).
Notation SEGS := asegs (only parsing).

Definition A_PRINTF_CORE : Z := 0x16e630.
Definition PC_RETPC : Z := 0x16f458.

Section Pass1.
  Context {fx : FPState}.
Variable gd : Z.
  Hypothesis Hgd : 0 <= gd < 2 ^ 64.

  Lemma pcore_pass1 : forall R M (sp ret fmt conv : Z),
    getr R 1%bv = Z_to_bv 64 ret -> ret_ok (Z_to_bv 64 ret) -> 0 <= ret < 2 ^ 64 ->
    getr R 2%bv = Z_to_bv 64 sp -> getr R 10%bv = Z_to_bv 64 0 -> getr R 11%bv = Z_to_bv 64 fmt ->
    2 ^ 32 <= sp - 544 -> sp < 2 ^ 47 -> sp mod 16 = 0 -> mdef M (sp - 544) 544 ->
    2 ^ 32 <= fmt -> fmt + 4 < 2 ^ 47 -> (fmt + 4 <= sp - 544 \/ sp <= fmt) ->
    fld SEGS M fmt 1 37 -> fld SEGS M (fmt + 1) 1 108 -> fld SEGS M (fmt + 2) 1 conv -> fld SEGS M (fmt + 3) 1 0 ->
    (conv = 117 \/ conv = 100 \/ conv = 120) ->
    mem_inv asegs M -> relro_clear M -> fld SEGS M A_CANARY 8 gd ->
    exists R' M',
      msteps SEGS (@mkst fx R (Z_to_bv 64 A_PRINTF_CORE) M (seg_rom SEGS)) (@mkst fx R' (Z_to_bv 64 ret) M' (seg_rom SEGS))
      /\ getr R' 10%bv = Z_to_bv 64 0
      /\ (forall r, In r leaf_kept -> getr R' r = getr R r)
      /\ stores_in (zwin (sp - 544) sp) M M'.
Proof.
